-- Consulta: F Movimento Contas Consulta
-- Tipo: Seleção (0)
-- Descrição: 

SELECT [F Movimento Contas].NumMovimento, Parceiros.NomeParceiro, EmpVinculada.NomeVinculada, [F Contas Financeiras].[Numero Conta], [F Contas Financeiras].Descricao, [F Movimento Contas].SomenteIntegracao, [F Movimento Contas].EmitirCheque, [F Movimento Contas].ReferenteNotaFiscal, [F Movimento Contas].PagamentoLote, [F Movimento Contas].LinkVenda, [F Movimento Contas].Plano1, [F Movimento Contas].Plano2, [F Movimento Contas].PagoAntecipado, [F Movimento Contas].Efetuado, [F Movimento Contas].SofreReajuste, [F Movimento Contas].CodAtribuiParceiro, [F Movimento Contas].CodAtribuiEmpresa, [F Movimento Contas].CodAnteriorParceiro, [F Movimento Contas].CodAnteriorEmpresa, [F Movimento Contas].EmpVinculada, [F Movimento Contas].SelPagtoLote, [F Movimento Contas].CodImovel, [F Movimento Contas].AgrupadorVenda, [F Movimento Contas].CodigoParceiro, [F Movimento Contas].MovPagtoLote, [F Movimento Contas].ContaFinanceira, [F Movimento Contas].Plano3, [F Movimento Contas].CodHistorico, [F Movimento Contas].NumDoc, [F Movimento Contas].Complemento, [F Movimento Contas].ValorDebito, [F Movimento Contas].ValorCredito, [F Movimento Contas].DataMovto, [F Movimento Contas].DataVencto, [F Movimento Contas].DataPagto, [F Movimento Contas].Confirmado, [F Movimento Contas].Integracao, [F Movimento Contas].Observacao
FROM EmpVinculada INNER JOIN (Parceiros INNER JOIN (Imoveis INNER JOIN (Historico INNER JOIN ([F Contas Financeiras] INNER JOIN [F Movimento Contas] ON [F Contas Financeiras].[CodigoConta] = [F Movimento Contas].[ContaFinanceira]) ON Historico.[CodHistorico] = [F Movimento Contas].[CodHistorico]) ON Imoveis.[CodImovel] = [F Movimento Contas].[CodImovel]) ON Parceiros.[CodigoParceiro] = [F Movimento Contas].[CodigoParceiro]) ON EmpVinculada.[CodigoVinculada] = [F Movimento Contas].[EmpVinculada];
